 49	import java.util.HashSet;
 50	import java.util.Set;
 51	
 52	public record Cell(int x, int y) {
 53	
 54	    public Set<Cell> neighbours() {
 55	        Set<Cell> neighbours = new HashSet<>();
 56	        for (int dx = -1; dx <= 1; dx++) {
 57	            for (int dy = -1; dy <= 1; dy++) {
 58	                if (dx != 0 || dy != 0) {
 59	                    neighbours.add(new Cell(x + dx, y + dy));
 60	                }
 61	            }
 62	        }
 63	        return neighbours;
 64	    }
 65	}
